/**
 * The counts both sides of the cross-check bind to.
 *
 * `packages/ui/test/morning-digest.test.tsx` asserts that `digestOf` produces
 * these over `WEEK_OF_RUNS`. `packages/daemon/test/overnight-digest-counts.test.ts`
 * replays the same rows into a real database and asserts that `GET
 * /analytics?days=5&to=NOW` — the identical window, since
 * `LAST_READ_LONG_WEEKEND` is exactly five days before `NOW` — produces them
 * too. Two suites, one set of numbers: if both pass, the digest and the
 * Analytics tab cannot be telling the user different things about the same
 * night.
 *
 * The four fields analytics does not compute (`needsYou`, `costUnreported`,
 * `branchesWaiting`, `exceptions`) are the digest's own and are asserted only
 * on the UI side; they are listed here so the whole expectation reads in one
 * place.
 */
export const EXPECTED_LONG_WEEKEND = {
  /** shared with GET /analytics */
  runs: 15,
  completed: 9,
  /** analytics' definition — `failed` + `timed_out`. The budget bust is not in it. */
  failed: 4,
  inFlight: 1,
  costUsd: 3.2,
  successRate: 64,
  /** the digest's own */
  finished: 14,
  needsYou: 1,
  costUnreported: 1,
  branchesWaiting: 2,
  /** 1 waiting on you + 4 failed + 1 over budget */
  exceptions: 6,
} as const;

